import './Login_User.css'
import React, { useState } from 'react';
import { FaEye, FaEyeSlash } from 'react-icons/fa';// Importamos los íconos de ojo abierto y cerrado

const LoginUser = ({setLogueo}) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  const handleUsernameChange = (event) => {
    setUsername(event.target.value);
  };

  const handlePasswordChange = (event) => {
    setPassword(event.target.value);
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    // Aquí podrías agregar la lógica para enviar los datos de inicio de sesión al servidor
    console.log('Usuario:', username);
    console.log('Contraseña:', password);
  };

  const hondleRecuperar = ()=>{
    alert("si Funciona")
    setLogueo('recuperarkey')
  } 

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="username">Usuario:</label>
        <input
          type="text"
          id="username"
          value={username}
          onChange={handleUsernameChange}
        />
      </div>
      <div>
        <label htmlFor="password">Contraseña:</label>
        <input
          type={showPassword ? 'text' : 'password'}
          id="password"
          value={password}
          onChange={handlePasswordChange}
        />
        <button type="button" onClick={togglePasswordVisibility}>
          {showPassword ? <FaEyeSlash/> : <FaEye />}
        </button>
      </div>
      <button type="submit">Iniciar sesión</button>
      <div onClick={() => setView("registro")}>olvidaste la contraseña</div>
    </form>
  );
};

export default LoginUser;
